import { mock } from 'node:test';
import { TestAdapter as BaseTestAdapter } from '@yeoman/adapter/testing';
export class TestAdapter extends BaseTestAdapter {
    constructor(options = {}) {
        super({
            spyFactory: ({ returns }) => returns
                ? mock.fn(() => { }, () => returns)
                : mock.fn(),
            ...options,
        });
    }
}
